module TopModule (
    input  clk,
    input  reset,
    input  [7:0] in,
    output reg [23:0] out_bytes,
    output reg done
);

    // State encoding
    typedef enum logic [1:0] {
        IDLE   = 2'b00,
        BYTE1  = 2'b01,
        BYTE2  = 2'b10,
        BYTE3  = 2'b11
    } state_t;

    state_t state, next_state;

    // Shift register to hold the 3 received bytes
    logic [23:0] shift_reg;

    // Next-state and output logic (combinational)
    always_comb begin
        next_state = state;
        done       = 1'b0;
        out_bytes  = 24'b0;

        case (state)
            IDLE: begin
                // Wait for in[3] to become 1
                if (in[3]) begin
                    next_state = BYTE1;
                    shift_reg  = {24{1'b0}}; // clear shift register
                end else begin
                    next_state = IDLE;
                end
            end

            BYTE1: begin
                // Store first byte, move to BYTE2
                shift_reg = {in, 16'b0}; // in is the MSB (byte 1)
                next_state = BYTE2;
            end

            BYTE2: begin
                // Shift in second byte (in becomes bits [15:8])
                shift_reg = {in, shift_reg[15:0]};
                next_state = BYTE3;
            end

            BYTE3: begin
                // Shift in third byte (in becomes bits [7:0])
                shift_reg = {in, shift_reg[7:0]};
                next_state = IDLE;
                done       = 1'b1; // assert done in the cycle after third byte
            end
        endcase
    end

    // Sequential logic (flip-flops) triggered on positive edge of clk
    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            state     <= IDLE;
            out_bytes <= 24'b0;
            done      <= 1'b0;
        end else begin
            state     <= next_state;
            out_bytes <= shift_reg;
            done      <= 1'b0; // done is pulse, cleared next cycle (or kept for one cycle as per example)
            // Based on the example waveform, done stays high for one cycle
            // and is cleared the next cycle. We assert it in the BYTE3 state
            // and clear it in the IDLE state transition.
        end
    end

    // Additional logic to clear done after one cycle if needed.
    // The above always_comb already handles asserting done in BYTE3.
    // The sequential always_ff resets done to 0 when reset is active.
    // For normal operation, done is asserted in the cycle after BYTE3
    // and naturally cleared the next cycle when state goes to IDLE
    // or BYTE1, etc., because the always_comb sets done = 0 by default
    // unless in BYTE3 state.

endmodule

