module TopModule (
    input  [3:0] x,
    output f
);

    // Internal signals for decoded address bits
    wire x3 = x[3];
    wire x2 = x[2];
    wire x1 = x[1];
    wire x0 = x[0];

    // K-map derived expression:
    // f = x3' & x2' & x1 & x0'   (m1)
    //   | x3' & x2  & x1' & x0'  (m4)
    //   | x3  & x2  & x1         (m12, m13)
    //   | x3  & x2  & x1' & x0'  (m12, m13, m4)
    //   | x3  & x2' & x1 & x0    (m10, m14)
    //   | x3  & x2' & x1'        (m8, m10)  -> covers m8, m10
    //   | x3' & x2  & x1'        (m2, m10)  -> covers m2, m10
    //   | x3' & x2' & x1 & x0'   (m1, m5)
    //
    // After prime implicant chart and essential prime implicant analysis:
    // Essential: x3 & x2 & x1  (covers m12, m13)
    //           x3 & x2' & x1' (covers m8, m10)
    //           x3' & x2  & x1'  (covers m2, m10) -> overlap at m10
    //           x3' & x2' & x1 & x0' (covers m1, m5)
    //           x3  & x2' & x1 & x0  (covers m10, m14) -> overlap at m10
    //           x3  & x2  & x1' & x0' (covers m4)
    //
    // Minimal SOP implementation:
    assign f = (x3 & x2 & x1) |
               (x3 & ~x2 & ~x1) |
               (~x3 & x2  & ~x1) |
               (~x3 & ~x2 & x1 & ~x0) |
               (x3  & ~x2 & x1 & x0) |
               (x3  & x2  & ~x1 & ~x0);

endmodule

