module TopModule (
    input  clk,
    input  a,
    output [2:0] q
);

    // Internal register to hold the state
    reg [2:0] q_reg;

    // Register to store previous value of a for edge detection
    reg a_prev;

    // Synchronous always block triggered on the rising edge of clk
    always @(posedge clk) begin
        // If 'a' is 1, q stays at 4'b100 (4)
        if (a) begin
            q_reg <= 3'b100; // 4 in decimal
        end else begin
            // When a is 0, check the previous state to determine reset or increment
            if (a_prev) begin
                // a transitioned from 1 to 0 (falling edge) -> reset to 0
                q_reg <= 3'b000;
            end else begin
                // a was 0, now 0 -> increment counter
                q_reg <= q_reg + 3'b001;
            end
        end
        // Update previous 'a' for the next clock cycle
        a_prev <= a;
    end

    // Assign the registered output
    assign q = q_reg;

endmodule

